import type { BallotPageProcessingStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

export const ballotPageValidationBadgeData: Record<
  BallotPageProcessingStatus,
  { label: string; variant: BadgeVariants }
> = {
  valid: {
    variant: 'success',
    label: 'Accepted',
  },
  soft_accepted: {
    variant: 'warning',
    label: 'Accepted',
  },
  invalid: {
    variant: 'destructive',
    label: 'Rejected',
  },
  processing: {
    variant: 'info',
    label: 'Processing',
  },
};

const defaultBallotPageValidationBadge: { label: string; variant: BadgeVariants } = { label: '', variant: 'default' };

export function getBallotPageValidationBadge(status: BallotPageProcessingStatus): {
  label: string;
  variant: BadgeVariants;
} {
  return (
    ballotPageValidationBadgeData[status] ?? {
      ...defaultBallotPageValidationBadge,
      label: snakeCaseToCapitalizedCase(status),
    }
  );
}
