import { submitBallotVerification } from '~/client';
import type { SubmitBallotVerificationRequest } from '~/client';

export const useSubmitBallots = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: SubmitBallotVerificationRequest) =>
      submitBallotVerification({
        composable: '$fetch',
        body: data,
      }),
    onSuccess: async () => {
      showToastSuccess(`Petitions submitted successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    submitBallots: mutateAsync,
    isSubmittingBallots: computed(() => asyncStatus.value === 'loading'),
  };
});
