<template>
  <Dialog v-model:open="open" @update:open="() => $emit('close')">
    <DialogContent class="max-w-3xl w-[95%]">
      <DialogHeader>
        <DialogTitle class="flex gap-2 items-center">
          <span>Petition page</span>
          <Badge :variant="badgeData.variant">{{ badgeData.label }}</Badge>
        </DialogTitle>
      </DialogHeader>
      <div class="flex flex-col gap-2 overflow-y-auto max-h-[70vh]">
        <Alert v-if="page.status === 'invalid'" class="flex gap">
          <AlertTitle class="flex gap-2 items-center">
            <AlertTriangle class="mr-2 min-w-5 min-h-5" />
            Reason: {{ page.error_msg || 'Unknown reason' }}
          </AlertTitle>
        </Alert>
        <img :src="page.s3_url" alt="Petition page image" class="w-full h-auto max-h-[80vh]" />
      </div>
      <DialogFooter class="flex gap-2">
        <Button
          variant="outline-destructive"
          :prepend-icon="TrashIcon"
          :loading="clickedButton === 'remove'"
          :disabled="!!clickedButton"
          @click="onRemoveClick"
          >Remove</Button
        >
        <Button
          v-if="isMobile"
          variant="outline"
          :prepend-icon="CameraIcon"
          :loading="clickedButton === 'takeAgain'"
          :disabled="!!clickedButton"
          @click="onTakeAgainClick"
          >Remove and Take Again</Button
        >
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import type { CanvasserBallotPage } from '~/client';
import { AlertTriangle, CameraIcon, TrashIcon } from 'lucide-vue-next';
import { getBallotPageValidationBadge } from '~/constants/ballotPageValidationBadgeData';

interface Props {
  page: CanvasserBallotPage;
  removePage: () => Promise<void>;
  removeAndTakeAgain: () => Promise<void>;
}

const props = defineProps<Props>();
const { isMobile } = useMobileForWeb();

interface Emits {
  (e: 'close'): void;
}

defineEmits<Emits>();

const open = defineModel<boolean>('open', { default: false });

const clickedButton = ref<'remove' | 'takeAgain' | null>(null);

async function onRemoveClick() {
  clickedButton.value = 'remove';
  await props.removePage();
  clickedButton.value = null;
}

async function onTakeAgainClick() {
  clickedButton.value = 'takeAgain';
  await props.removeAndTakeAgain();
  clickedButton.value = null;
}

const badgeData = computed(() => {
  return getBallotPageValidationBadge(props.page.status);
});
</script>
