<template>
  <section class="flex flex-col gap-10">
    <PageTitle title="Import Petitions" />
    <div class="flex flex-col gap-4">
      <GoBackButton
        subject="selection"
        :fallback-to="{
          name: 'verification-ballots-configuration',
          query: useRoute().query,
        }"
      />
      <Card class="max-w-4xl w-full mx-auto">
        <CardHeader>
          <Alert v-if="isUploadOnCanvassersBehalf" variant="warning">
            <InfoIcon />
            <AlertTitle>{{ importOnBehalfAlert.title }}</AlertTitle>
            <AlertDescription>
              {{ importOnBehalfAlert.note }}<br />
              {{ importOnBehalfAlert.caution }}
            </AlertDescription>
          </Alert>
        </CardHeader>
        <CardContent>
          <AppLoader v-if="isLoading && ballots.length === 0" variant="inline" subject="petitions" />
          <AppError v-else-if="error" title="Failed to load petitions" :message="error" />
          <div v-else-if="projectId && canvasserId" class="flex flex-col gap-4">
            <div class="grid grid-cols-1 gap-4 md:grid-cols-2">
              <LabeledEntityProject :project-id="projectId" />
              <LabeledEntityUser v-if="isManager" :user-id="canvasserId" />
            </div>

            <div class="flex flex-col gap-6">
              <VerificationBallotsListItem
                v-for="(ballot, index) in ballots"
                :key="ballot.ballot_id"
                :ballot="ballot"
                :index="index + 1"
                :canvasser-id="canvasserId"
                :project-id="projectId"
                :ballot-template="ballot.ballot_template"
              />
              <Button
                variant="outline"
                class="mx-auto"
                :prepend-icon="FilePlusIcon"
                :disabled="isAddNewBallotLoading"
                :loading="isAddNewBallotLoading"
                @click="addNewBallotClick"
                >New Petition</Button
              >
              <template v-if="ballots.length === 0">
                <Separator label="OR" class="my-4" />
                <AppLoader v-if="isUploadingBallotBatch" variant="inline" />
                <div v-else class="mx-auto">
                  <FileUploadInput
                    id="pdf-upload-batch"
                    v-slot="{ isLoading: isFileUploading }"
                    class="mx-auto"
                    :accept="['application/pdf']"
                    :max-files="1"
                    :is-toast-error="true"
                    @change="uploadBallotsBatchHandler"
                  >
                    <Button
                      as="label"
                      for="pdf-upload-batch"
                      variant="outline"
                      :prepend-icon="FileStackIcon"
                      :disabled="isFileUploading"
                      :loading="isFileUploading"
                    >
                      Batch upload via PDF
                    </Button>
                  </FileUploadInput>
                </div>
              </template>
            </div>
          </div>
        </CardContent>
        <CardFooter v-if="!(isLoading && ballots.length === 0)" class="justify-end">
          <Button
            class="h-10 px-4"
            variant="default"
            :disabled="disableStepBtn || isSubmittingBallots"
            :loading="isSubmittingBallots"
            @click="onSubmitClick"
          >
            Submit
          </Button>
        </CardFooter>
      </Card>
    </div>
  </section>
</template>

<script setup lang="ts">
import { FilePlusIcon, FileStackIcon, InfoIcon, UploadIcon } from 'lucide-vue-next';
import { FetchError } from 'ofetch';
import { useBallotDrafts } from '~/queries/verification/ballot';
import { useAddBallot } from '~/mutations/verification/addBallot';
import { useSubmitBallots } from '~/mutations/verification/submitBallots';
import LabeledEntityProject from '~/components/common/labeled-entity/LabeledEntityProject.vue';
import LabeledEntityUser from '~/components/common/labeled-entity/LabeledEntityUser.vue';
import {
  type BallotUploadBatchRequest,
  type BallotUploadFilesRequest,
  type FileUploadResponse,
  uploadBallotBatch,
  type UploadBallotBatchData,
  uploadBallotFiles,
  type UploadBallotFilesData,
} from '~/client';
import { showToastInfo } from '~/utils/show-toast';
import { importOnBehalfAlert } from '~/constants/verifications/importOnBehalfAlert';

definePageMeta({
  roles: ['canvasser', 'subcontractor_canvasser', 'manager'],
});

useHead({
  title: 'Import Petitions',
});

const route = useRoute();

const { isManager } = useUserRole();

const setupErrorDetails = ref<null | string>(null);

const disableStepBtn = computed<boolean>(() => {
  return !canSubmit.value;
});

const {
  isLoading,
  canvasserId,
  projectId,
  isUploadOnCanvassersBehalf,
  ballots,
  canSubmit,
  error: ballotError,
  refetch,
} = useBallotDrafts();

const { addNewBallot, isAddNewBallotLoading } = useAddBallot();

async function addNewBallotClick() {
  await addNewBallot({
    project_id: projectId.value,
    canvasser_id: canvasserId.value,
  }).catch((err: FetchError) => {
    console.error('Error adding new petition:', err);
  });
}

const { submitBallots, isSubmittingBallots } = useSubmitBallots();

async function onSubmitClick() {
  await submitBallots({
    project_id: projectId.value,
    canvasser_id: canvasserId.value,
    is_upload_on_canvassers_behalf: isUploadOnCanvassersBehalf.value,
  })
    .then(async () => {
      await navigateTo({
        name: 'verification-ballots-configuration',
        query: {
          ...route.query,
        },
      });
      useQueryCache().setQueryData(['ballots.list.draft', projectId.value, canvasserId.value], () => undefined);
    })
    .catch((err: FetchError) => {
      console.error('Error submitting petitions:', err);
    });
}

const error = computed(() => {
  if (ballotError.value) {
    return ballotError.value.data.detail || 'Failed to load petitions';
  } else if (setupErrorDetails.value) {
    return setupErrorDetails.value;
  }
});

useTimeoutPoll(async () => {
  if (ballots.value.length === 0) return;
  const isPageProcessing = ballots.value.find((ballot) => {
    return ballot.pages?.find((page) => page.status === 'processing');
  });
  if (isPageProcessing)
    await refetch().catch((error) => {
      console.error('Error refetching petitions list:', error);
    });
}, 10000);

const { mutateAsync: uploadBallotBatchMutation, isLoading: isUploadingBallotBatch } = useMutation({
  mutation: (data: { body: BallotUploadBatchRequest }) =>
    uploadBallotBatch({
      composable: '$fetch',
      body: data.body,
    }),
  key: () => ['ballots.uploadFiles', projectId.value, canvasserId.value],
  onSuccess: async (data, { body }) => {
    const queryCache = useQueryCache();
    queryCache.setQueryData(['ballots.list.draft', body.project_id, body.canvasser_id], () => {
      return data;
    });
    showToastSuccess(`Files uploaded successfully`);
  },
  onError(error) {
    showToastError(error);
  },
});

async function uploadBallotsBatchHandler(files: FileUploadResponse[]) {
  showToastInfo('Uploaded file, creating petitions...');
  await uploadBallotBatchMutation({
    body: {
      files: files.map((file) => file.private_url),
      project_id: projectId.value,
      canvasser_id: canvasserId.value,
    },
  });
}
</script>

<style scoped lang="scss"></style>
