import { removeBallot as removeBallotApi } from '~/client';
import type { RemoveBallotData } from '~/client';

export const useRemoveBallot = defineMutation(() => {
  const pendingRemoveBallotId = ref<string | null>(null);

  const { mutateAsync } = useMutation({
    mutation: (data: { path: RemoveBallotData['path']; canvasserId: string; projectId: string }) =>
      removeBallotApi({
        composable: '$fetch',
        path: data.path,
      }),
    onSuccess: async (data, requestData) => {
      const queryCache = useQueryCache();
      queryCache.setQueryData(['ballots.list.draft', requestData.projectId, requestData.canvasserId], () => {
        return data;
      });
      showToastSuccess('Petition removed successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  async function removeBallot(data: { path: RemoveBallotData['path']; canvasserId: string; projectId: string }) {
    pendingRemoveBallotId.value = data.path.ballot_id;
    try {
      await mutateAsync(data);
    } finally {
      pendingRemoveBallotId.value = null;
    }
  }

  return {
    removeBallot,
    pendingRemoveBallotId: readonly(pendingRemoveBallotId),
  };
});
