<template>
  <ImagesPreview
    :url="page.s3_url"
    :is-loading="false"
    :is-square="false"
    :is-preloader="page.status === 'processing' || isRemoveLoading"
    :delete="removePageFunc"
    class="aspect-square"
    @click="
      () => {
        if (!isRemoveLoading) isDetailsOpen = true;
      }
    "
  />
  <span>Page #{{ pageIndex + 1 }}</span>
  <Badge :variant="getBallotPageValidationBadge(page.status).variant"
    >{{ getBallotPageValidationBadge(page.status).label }}
  </Badge>
  <VerificationBallotsPageDetails
    v-model:open="isDetailsOpen"
    :page="page"
    :remove-page="removePageFunc"
    :remove-and-take-again="removeAndTakeAgainFromDialog"
    @close="isDetailsOpen = false"
  />
</template>

<script setup lang="ts">
import { removeBallotPage } from '~/client';
import { getBallotPageValidationBadge } from '~/constants/ballotPageValidationBadgeData';
import type { RemoveBallotPageData, CanvasserBallotPage } from '~/client';

interface Props {
  page: CanvasserBallotPage;
  canvasserId: string;
  projectId: string;
  pageIndex: number;
  ballotId: string;
}

const props = defineProps<Props>();

const isDetailsOpen = ref<boolean>(false);

const { mutateAsync: removePage, asyncStatus } = useMutation({
  mutation: (data: { path: RemoveBallotPageData['path']; canvasserId: string; projectId: string }) =>
    removeBallotPage({
      composable: '$fetch',
      path: data.path,
    }),
  onSuccess: async (data, requestData) => {
    const queryCache = useQueryCache();
    queryCache.setQueryData(['ballots.list.draft', requestData.projectId, requestData.canvasserId], () => {
      return data;
    });
    showToastSuccess(`Page removed successfully`);
  },
  onError(error) {
    showToastError(error);
  },
});

async function removePageFunc() {
  await removePage({
    path: {
      page_id: props.page.page_id || '',
    },
    canvasserId: props.canvasserId,
    projectId: props.projectId,
  });
}

const isRemoveLoading = computed(() => asyncStatus.value === 'loading');

const route = useRoute();

async function removeAndTakeAgainFromDialog() {
  await removePageFunc().then(() => (isDetailsOpen.value = false));

  await navigateTo({
    name: 'verification-ballots-import-id-camera',
    params: { id: props.ballotId },
    query: route.query,
  });
}
</script>
