<template>
  <FormField
    v-slot="slots"
    :validate-on-model-update="false"
    :validate-on-change="false"
    :validate-on-blur="false"
    :validate-on-mount="false"
    :name="id"
  >
    <FormItem as-child>
      <FormControl>
        <slot :is-loading="isLoading" />
        <Input
          :id="id"
          type="file"
          :multiple="isMultiple"
          :disabled="disabled"
          :accept="(accept || ['*']).join(',')"
          class="hidden"
          @change="
            async (event: Event) => {
              slots.handleChange(event);
              await submit();
            }
          "
        />
        <FormMessage v-if="!isToastError" />
      </FormControl>
    </FormItem>
  </FormField>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { FileUploadResponse } from '~/client';

interface Emits {
  (e: 'change', event: FileUploadResponse[]): void;
}

const emits = defineEmits<Emits>();

interface Props {
  id: string;
  label?: string;
  disabled?: boolean;
  accept?: string[];
  maxFiles: number;
  maxSizeMB?: number;
  isToastError?: boolean;
}

const props = defineProps<Props>();
const isLoading = ref(false);
const isMultiple = computed(() => props.maxFiles > 1);

const errorMessages = {
  maxFiles: `Maximum ${props.maxFiles} files allowed`,
  fileType: `Invalid file type. File should be one of ${props.accept?.join(',')}`,
  maxFileSize: `File size should not exceed ${props.maxSizeMB}MB`,
};

const errorTitle = 'File Validation Error';

const singleInputSchema = toTypedSchema(
  z.object({
    [props.id]: z
      .instanceof(File)
      .refine(
        (file) => {
          if (props.accept) {
            const check = props.accept?.includes(file.type);
            if (!check && props.isToastError) showToastError(errorMessages.fileType, errorTitle);
            return check;
          } else {
            return true;
          }
        },
        { message: errorMessages.fileType }
      )
      .refine(
        (file) => {
          if (props.maxSizeMB) {
            const check = file.size <= props.maxSizeMB * 1024 * 1024;
            if (!check && props.isToastError) showToastError(errorMessages.maxFileSize, errorTitle);
            return check;
          } else {
            return true;
          }
        },
        { message: errorMessages.maxFileSize }
      )
      .transform((file) => [file]),
  })
);

const multipleInputSchema = toTypedSchema(
  z.object({
    [props.id]: z
      .instanceof(File)
      .array()
      .refine(
        (list) => {
          if (props.maxFiles) {
            const check = list.length <= props.maxFiles;
            if (!check && props.isToastError) showToastError(errorMessages.maxFiles, errorTitle);
            return check;
          } else {
            return true;
          }
        },
        { message: errorMessages.maxFiles }
      )
      .refine(
        (files) => {
          if (props.accept) {
            const check = files.every((file) => props.accept?.includes(file.type));
            if (!check && props.isToastError) showToastError(errorMessages.fileType, errorTitle);
            return check;
          } else {
            return true;
          }
        },
        { message: errorMessages.fileType }
      )
      .refine(
        (files) => {
          if (props.maxSizeMB) {
            const maxSizeMB = props.maxFiles ?? 0;
            const check = files.every((file) => file.size <= maxSizeMB * 1024 * 1024);
            if (!check && props.isToastError) showToastError(errorMessages.maxFileSize, errorTitle);
            return check;
          } else {
            return true;
          }
        },
        {
          message: errorMessages.maxFileSize,
        }
      ),
  })
);

const { handleSubmit: submitInput } = useForm({
  validationSchema: isMultiple.value ? multipleInputSchema : singleInputSchema,
  initialValues: { [props.id]: [] } as any,
});

const { uploadFileData } = useUploadFile();

const submit = submitInput(async (values) => {
  let files = values[props.id];

  if (files.length === 0) {
    emits('change', []);
    return;
  }

  if (!Array.isArray(files)) {
    files = [files];
  }

  isLoading.value = true;

  try {
    const processedFiles: FileUploadResponse[] = [];
    for (const file of files) {
      const uploadResult = await uploadFileData({ file: file });
      if (uploadResult) {
        processedFiles.push(uploadResult);
      }
    }
    emits('change', processedFiles);
  } finally {
    isLoading.value = false;
  }

  // todo: refactor to use Promise.allSettled
  // const uploadPromises: Array<Promise<FileUploadResponse> | null> = [];
  // files.forEach((file, index) => {
  //   processedFiles.push({
  //     private_url: '',
  //     public_url: '',
  //     isLoading: true,
  //     uploadResult: uploadFileData({ file: file }),
  //   });
  //   if (processedFiles[index].uploadResult) uploadPromises.push(processedFiles[index].uploadResult);
  // });
  // await Promise.allSettled(uploadPromises).then((results) => {
  //   results.forEach((result, index) => {
  //     if (result.status === 'rejected') {
  //       showToastError(files[index].name, 'Failed to upload file: ');
  //     } else if (result.value) {
  //       processedFiles[index] = {
  //         private_url: result.value?.private_url,
  //         public_url: result.value?.public_url,
  //       };
  //     }
  //   });
  //   processedFiles = processedFiles.filter((file) => file.uploadResult);
  //   emits('change', processedFiles);
  // });
});

function clearInput() {
  const imageInput = document.querySelector('.image-upload-form input[type="file"]') as HTMLInputElement;
  if (imageInput) {
    imageInput.value = '';
    imageInput.removeAttribute('disabled');
    emits('change', []);
  }
}
</script>
