<template>
  <div class="flex flex-col gap-2">
    <div class="flex justify-between items-center gap-2">
      <div class="flex items-center gap-2 flex-wrap">
        <span class="text-xl">Petition #{{ index }}</span>
        <Badge v-if="ballot.pages.length > 0" class="gap-2 lowercase text-nowrap"
          ><span>{{ ballot.valid_pages }} of {{ ballot.pages.length }}</span>
          <Check class="w-4 h-4 text-success-foreground stroke-2" />
        </Badge>
        <Badge v-if="ballot.error_message" variant="destructive" class="text-nowrap">{{ ballot.error_message }}</Badge>
      </div>
      <Button
        variant="outline-destructive"
        class="aspect-square"
        :loading="isThisBallotRemoving"
        :disabled="isOtherBallotRemoving"
        :prepend-icon="Trash"
        @click="removeBallot({ path: { ballot_id: ballot.ballot_id }, canvasserId: canvasserId, projectId: projectId })"
      >
        Remove
      </Button>
    </div>

    <div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
      <div
        v-for="(page, i) in ballot.pages"
        :key="page.page_id"
        class="flex flex-col gap-1 justify-center items-center"
      >
        <!-- TODO update ImagesPreview component with delete prop or create another component for such cases -->
        <VerificationBallotsImagePreview
          :ballot-id="ballot.ballot_id"
          :canvasser-id="canvasserId"
          :page="page"
          :page-index="i"
          :project-id="projectId"
        />
      </div>
      <template v-if="ballotTemplate.max_pages > ballot.pages.length">
        <div v-if="Capacitor.isNativePlatform()" class="aspect-square">
          <NuxtLink
            :to="{
              name: 'verification-ballots-import-id-camera',
              params: { id: ballot.ballot_id },
              query: { canvasser_id: canvasserId, project_id: projectId },
            }"
          >
            <Button variant="outline" class="w-full h-full shadow-md rounded-lg" :prepend-icon="FilePlus2Icon">
              New Page
            </Button>
          </NuxtLink>
        </div>
        <Card class="aspect-square w-full">
          <CardContent class="w-full h-full flex flex-col items-center justify-center">
            <Spinner v-if="isUploadingBallotFiles" class="w-12 h-12" />
            <template v-else>
              <FileUploadInput
                :id="`images-upload-${ballot.ballot_id}`"
                v-slot="{ isLoading }"
                :max-files="ballotTemplate.max_pages"
                :accept="['image/png', 'image/jpg', 'image/jpeg']"
                :is-toast-error="true"
                @change="uploadFileAndPages"
              >
                <Button
                  as="label"
                  :for="`images-upload-${ballot.ballot_id}`"
                  variant="outline"
                  :prepend-icon="UploadIcon"
                  :loading="isLoading"
                >
                  Upload images
                </Button>
              </FileUploadInput>
              <Separator label="OR" class="my-4" />
              <FileUploadInput
                :id="`pdf-upload-${ballot.ballot_id}`"
                v-slot="{ isLoading }"
                :accept="['application/pdf']"
                :max-files="1"
                :is-toast-error="true"
                @change="uploadFileAndPages"
              >
                <Button
                  as="label"
                  :for="`pdf-upload-${ballot.ballot_id}`"
                  variant="outline"
                  :prepend-icon="UploadIcon"
                  :loading="isLoading"
                >
                  Upload PDF
                </Button>
              </FileUploadInput>
            </template>
          </CardContent>
        </Card>
      </template>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Trash, Check, FilePlus2Icon, UploadIcon } from 'lucide-vue-next';
import {
  type BallotUploadFilesRequest,
  type CanvasserBallot,
  type CanvasserBallotTemplate,
  type FileUploadResponse,
  uploadBallotFiles,
  type UploadBallotFilesData,
} from '~/client';
import { useRemoveBallot } from '~/mutations/verification/removeBallot';
import { showToastInfo } from '~/utils/show-toast';
import { Capacitor } from '@capacitor/core';
import { Spinner } from '~/assets/icons';

interface Props {
  ballot: CanvasserBallot;
  ballotTemplate: CanvasserBallotTemplate;
  index: number;
  canvasserId: string;
  projectId: string;
}

const props = defineProps<Props>();

const { removeBallot, pendingRemoveBallotId } = useRemoveBallot();

const isThisBallotRemoving = computed(() => pendingRemoveBallotId.value === props.ballot.ballot_id);
const isOtherBallotRemoving = computed(
  () => pendingRemoveBallotId.value !== null && pendingRemoveBallotId.value !== props.ballot.ballot_id
);

const { mutateAsync: uploadBallotFilesMutation, isLoading: isUploadingBallotFiles } = useMutation({
  mutation: (data: {
    path: UploadBallotFilesData['path'];
    body: BallotUploadFilesRequest;
    projectId: string;
    canvasserId: string;
  }) =>
    uploadBallotFiles({
      composable: '$fetch',
      body: data.body,
      path: data.path,
    }),
  key: () => ['ballots.uploadFiles', props.ballot.ballot_id],
  onSuccess: async (data, requestData) => {
    const queryCache = useQueryCache();
    queryCache.setQueryData(['ballots.list.draft', requestData.projectId, requestData.canvasserId], () => {
      return data;
    });
    showToastSuccess(`Files uploaded successfully`);
  },
  onError(error) {
    showToastError(error);
  },
});

async function uploadFileAndPages(files: FileUploadResponse[]) {
  showToastInfo('Uploaded files, creating pages...');
  await uploadBallotFilesMutation({
    path: { ballot_id: props.ballot.ballot_id },
    body: { files: files.map((file) => file.private_url) },
    projectId: props.projectId,
    canvasserId: props.canvasserId,
  });
}
</script>
